  (0, 1, 'trade-flow-profile', 'f_suppliers.name', 'Name', 'entity_name', 'group', 'supplier identifier exactly as the source gives it: the company name where named, or the row label verbatim (e.g. ''Supplier 1'') where the source uses positional labels. Transcribe; never substitute, infer or blank it.', 'f_suppliers', 93),
  (0, 1, 'trade-flow-profile', 'f_suppliers.location', 'Location', 'text', 'group', 'country, region, or city of the supplier, if stated', 'f_suppliers', 94),
  (0, 1, 'trade-flow-profile', 'f_suppliers.commodity', 'Commodity', 'text', 'group', 'what is bought from this supplier, if stated', 'f_suppliers', 95),
  (0, 1, 'trade-flow-profile', 'f_suppliers.payment_terms', 'Payment Terms', 'text', 'group', 'payment terms expected or in place with this supplier (e.g. CAD, prepayment, 30 days, LC), if stated', 'f_suppliers', 96),
  (0, 1, 'trade-flow-profile', 'f_suppliers.relationship_length', 'Relationship Length', 'text', 'group', 'how long the entity has traded with them, if stated', 'f_suppliers', 97),
  (0, 1, 'trade-flow-profile', 'f_suppliers', 'Suppliers', 'group', 'group', 'One record per supplier the source identifies, whether the source lists them in a table or describes them in prose. Capture every supplier it identifies, in the order given. Where a supplier is identified only by a positional or placeholder label rather than a company name (e.g. ''Supplier 1'' in an anonymised schedule), still capture the record and put that label in `name` exactly as written: whether such a label counts as a name is not a judgement to make here, and the remaining details are needed either way. Never substitute or infer a name. Do not add suppliers the source does not identify.', 'f_suppliers', 98),
  (0, 1, 'trade-flow-profile', 'f_buyers.name', 'Name', 'entity_name', 'group', 'buyer identifier exactly as the source gives it: the company name where named, or the row label verbatim (e.g. ''Buyer 1'') where the source uses positional labels. Transcribe; never substitute, infer or blank it.', 'f_buyers', 99),
  (0, 1, 'trade-flow-profile', 'f_buyers.location', 'Location', 'text', 'group', 'country, region, or city of the buyer, if stated', 'f_buyers', 100),
  (0, 1, 'trade-flow-profile', 'f_buyers.commodity', 'Commodity', 'text', 'group', 'what is sold to this buyer, if stated', 'f_buyers', 101),
  (0, 1, 'trade-flow-profile', 'f_buyers.payment_terms', 'Payment Terms', 'text', 'group', 'payment terms sought or in place with this buyer (e.g. CAD, LC, open account, days credit), if stated', 'f_buyers', 102),
  (0, 1, 'trade-flow-profile', 'f_buyers.relationship_length', 'Relationship Length', 'text', 'group', 'how long the entity has traded with them, if stated', 'f_buyers', 103),
  (0, 1, 'trade-flow-profile', 'f_buyers', 'Buyers', 'group', 'group', 'One record per buyer or customer the source identifies, whether the source lists them in a table or describes them in prose. Capture every buyer it identifies, in the order given. Where a buyer is identified only by a positional or placeholder label rather than a company name (e.g. ''Buyer 1'' in an anonymised schedule), still capture the record and put that label in `name` exactly as written: whether such a label counts as a name is not a judgement to make here, and the remaining details are needed either way. Never substitute or infer a name. Do not add buyers the source does not identify.', 'f_buyers', 104);

