  (1, 1, 'articles', 'Articles of Association', 'corp', 'The entity''s articles of association or constitutional document, setting out share classes, director powers and internal rules.', 'text', 0, 0),
  (1, 1, 'bylaws', 'Bylaws', 'corp', 'Internal governance rules or bylaws adopted by the entity.', 'text', 0, 1),
  (1, 1, 'good-standing', 'Certificate of Good Standing', 'corp', 'A certificate issued by a registry confirming the entity exists and is in good standing at a stated date.', 'text', 0, 2),
  (1, 1, 'certificate-of-incorporation', 'Certificate of Incorporation', 'corp', 'The registry certificate recording that the entity was incorporated: legal name, registration number and date.', 'text', 0, 3),
  (1, 1, 'board-resolution', 'Board Resolution', 'corp', 'A minuted resolution of the board or members, typically authorising an act or appointing signatories.', 'text', 0, 4),
  (1, 1, 'beneficial-ownership', 'Beneficial Ownership Declaration', 'corp', 'A declaration naming the ultimate beneficial owners and their percentage holdings.', 'forms', 0, 5),
  (1, 1, 'regulatory-filings', 'Regulatory Filings', 'corp', 'An extract or filing made to a company registry or regulator: annual return, register extract, officer or shareholder filing. Records what the registry holds, not what the entity says about itself.', 'forms', 0, 6),
  (1, 1, 'cap-table', 'Cap Table or Share Instrument', 'corp', 'A share register, cap table, or an instrument affecting share ownership: share purchase agreement, option, warrant or pledge.', 'forms', 0, 7),
  (1, 1, 'aml-policy', 'AML Policy', 'kyc-aml-pep', 'The entity''s own anti-money-laundering or counter-terrorist-financing policy document.', 'text', 0, 8),
  (1, 1, 'cdd-questionnaire', 'CDD Questionnaire', 'kyc-aml-pep', 'A completed questionnaire or information request in which the entity answers questions about ITSELF: legal name, ownership, directors, business activity, banking, trade flows, financing sought. Question-and-answer or form format, completed by or on behalf of the entity being reviewed.', 'forms', 0, 9),
  (1, 1, 'id-verification', 'Identity Verification', 'kyc-aml-pep', 'Identity documents or verification evidence for a named individual: passport, national identity card, proof of address.', 'forms', 0, 10),
  (1, 1, 'pep-screen', 'PEP Screening', 'kyc-aml-pep', 'The output of a politically-exposed-person screening run against named individuals.', 'text', 0, 11),
  (1, 1, 'sanctions-screen', 'Sanctions Screening', 'kyc-aml-pep', 'The output of a sanctions list screening run against the entity or named individuals.', 'text', 0, 12),
  (1, 1, 'source-of-funds', 'Source of Funds', 'kyc-aml-pep', 'A statement or evidence of where the entity''s funds or a person''s wealth originated.', 'text', 0, 13),
  (1, 1, 'audited-statements', 'Audited Financial Statements', 'financial', 'Financial statements bearing an auditor''s report.', 'forms', 1, 14),
  (1, 1, 'interim-statements', 'Interim Financial Statements', 'financial', 'Management-prepared or unaudited financial statements for a period.', 'forms', 1, 15),
  (1, 1, 'tax-returns', 'Tax Returns', 'financial', 'A filed tax return or tax assessment.', 'forms', 0, 16),
  (1, 1, 'bank-statements', 'Bank Statements', 'financial', 'Statements of account issued by a bank showing transactions over a period.', 'forms', 1, 17),
  (1, 1, 'aging-reports', 'Aged Debtors or Creditors', 'financial', 'An aged debtors or aged creditors schedule showing amounts outstanding by age.', 'forms', 1, 18),
  (1, 1, 'counterparty-list', 'Customer or Supplier List', 'business', 'A schedule or list OF the entity''s customers, buyers or suppliers - names, locations, volumes or terms, usually tabular. A list of third parties, not a questionnaire about the entity itself.', 'text', 0, 19),
  (1, 1, 'market-analysis', 'Market Analysis', 'business', 'Analysis or commentary on the market, sector or commodity the entity trades in.', 'text', 0, 20),
  (1, 1, 'operations-memo', 'Operations Memorandum', 'business', 'A description of how the entity operates: sourcing, logistics, processing, warehousing, settlement.', 'text', 0, 21),
  (1, 1, 'trade-references', 'Trade References', 'business', 'A reference given by a trading partner, bank or customer about dealings with the entity.', 'text', 0, 22),
  (1, 1, 'trade-summary', 'Trade Summary', 'business', 'A summary of completed or planned trades, typically tabular: counterparties, commodities, volumes, values.', 'text', 0, 23),
  (1, 1, 'licenses-certificates', 'Licences and Certificates', 'business', 'A licence, permit, registration or certification held by a named party: regulatory licence, import permit, quality or scheme certification.', 'forms', 0, 24),
  (1, 1, 'insurance-coverage', 'Insurance Policy', 'business', 'An insurance policy, certificate or schedule: cargo, stock throughput, credit or liability cover.', 'forms', 0, 25),
