  (1, 1, 'KYC', 'f_screening_result', 'Screening Result', 'text', 'one', 'Overall screening outcome as stated (clear / match / potential match).', NULL, 35),
  (1, 1, 'KYC', 'f_pep_matches', 'Pep Matches', 'entity_name', 'many', 'Named individuals flagged as PEPs, with role/position if stated.', NULL, 36),
  (1, 1, 'KYC', 'f_sanctions_matches', 'Sanctions Matches', 'entity_name', 'many', 'Named individuals and entities flagged as sanctioned.', NULL, 37),
  (1, 1, 'KYC', 'f_product_and_port', 'Product And Port', 'text', 'many', 'Screening of products and ports.', NULL, 38),
  (1, 1, 'KYC', 'f_source_of_funds', 'Source Of Funds', 'text', 'one', 'Description of source of wealth and of equity in the company.', NULL, 39),
  (1, 1, 'KYC', 'f_associated_entities', 'Associated Entities', 'entity_name', 'many', 'Entities or organizations connected to any flagged person.', NULL, 40),
  (1, 1, 'KYC', 'f_id_verified', 'Id Verified', 'text', 'one', 'Method and confirmation of identity verification of all persons and entities.', NULL, 41),
  (1, 1, 'KYC', 'f_ownership_and_control', 'Ownership And Control', 'entity_name', 'many', 'Named individuals and entities which own and/or control the company.', NULL, 42),
  (1, 1, 'KYC', 'f_screening_provider', 'Screening Provider', 'text', 'one', 'The screening tool/vendor or source, if stated.', NULL, 43),
  (1, 1, 'KYC', 'f_screening_date', 'Screening Date', 'date', 'one', 'Date the screening was performed, if stated.', NULL, 44),
  (1, 1, 'KYC', 'f_risk_notes', 'Risk Notes', 'text', 'one', 'Any stated risk commentary, disposition, or analyst note.', NULL, 45),
  (1, 1, 'KYC', 'f_persons.full_name', 'Full Name', 'entity_name', 'group', 'full legal name as stated', 'f_persons', 46),
  (1, 1, 'KYC', 'f_persons.role', 'Role', 'text', 'group', 'role/capacity: UBO, director, signatory, or as stated', 'f_persons', 47),
  (1, 1, 'KYC', 'f_persons.ownership_pct', 'Ownership Pct', 'number', 'group', 'percentage owned, if stated for this person', 'f_persons', 48),
  (1, 1, 'KYC', 'f_persons.date_of_birth', 'Date Of Birth', 'date', 'group', 'date of birth, if stated', 'f_persons', 49),
  (1, 1, 'KYC', 'f_persons.nationality', 'Nationality', 'text', 'group', 'nationality/nationalities, if stated', 'f_persons', 50),
  (1, 1, 'KYC', 'f_persons.residential_address', 'Residential Address', 'address', 'group', 'residential address, if stated', 'f_persons', 51),
  (1, 1, 'KYC', 'f_persons.id_document', 'Id Document', 'identifier', 'group', 'ID document type and number, if stated', 'f_persons', 52),
  (1, 1, 'KYC', 'f_persons.pep_status', 'Pep Status', 'text', 'group', 'PEP status/flag for this person, if stated', 'f_persons', 53),
  (1, 1, 'KYC', 'f_persons', 'Persons', 'group', 'group', 'One record per natural person (UBO, director, officer or authorised signatory) OF THE ENTITY named in the document. Include only persons actually named; do not invent. Do NOT include a person who merely certified, witnessed, stamped, notarised or filed the document, or a registry official processing it - they are not parties to the entity.', 'f_persons', 54),
  (1, 1, 'KYC', 'f_financial_counterparties.name', 'Name', 'entity_name', 'group', 'institution name exactly as the source gives it; transcribe, never expand an abbreviation or correct a spelling', 'f_financial_counterparties', 55),
  (1, 1, 'KYC', 'f_financial_counterparties.type', 'Type', 'text', 'group', 'one of: bank, insurer, insurance-broker, warehouse. Use the term the source supports; if the source does not make the type clear, leave null rather than guessing', 'f_financial_counterparties', 56),
  (1, 1, 'KYC', 'f_financial_counterparties.role', 'Role', 'text', 'group', 'what it does for the entity as stated (e.g. operating account, collections, stock throughput cover, credit insurance, storage), if stated', 'f_financial_counterparties', 57),
  (1, 1, 'KYC', 'f_financial_counterparties.jurisdiction', 'Jurisdiction', 'text', 'group', 'country or location of the institution, if stated', 'f_financial_counterparties', 58),
  (1, 1, 'KYC', 'f_financial_counterparties', 'Financial Counterparties', 'group', 'group', 'One record per BANK, INSURER, INSURANCE BROKER or WAREHOUSE/COLLATERAL OPERATOR the source connects to the entity. These are the counterparties a lender must see: who holds the cash, who carries the cargo and credit risk, and who holds the goods. Capture each one the source identifies, including those also named elsewhere in the document. Do not include buyers, suppliers, parents, subsidiaries, inspection or certification bodies, or regulators - those belong to other fields.', 'f_financial_counterparties', 59),
  (1, 1, 'aml-policies-summary', 'f_policy_provided', 'Policy Provided', 'text', 'one', 'Whether this document is, or contains, an AML/CTF policy or programme description. Answer ''yes'' or ''no'' based only on what the document is. Do not comment on whether the counterparty has a programme — only on what this document contains.', NULL, 60),
  (1, 1, 'aml-policies-summary', 'f_policy_document', 'Policy Document', 'text', 'one', 'Identification of the document as stated: title, issuing entity, version, effective or approval date, and review cycle, to the extent given.', NULL, 61),
  (1, 1, 'aml-policies-summary', 'f_compliance_officer', 'Compliance Officer', 'text', 'one', 'The named compliance officer, MLRO, or responsible person, with title, if the document states one.', NULL, 62),
  (1, 1, 'aml-policies-summary', 'f_policy_summary', 'Policy Summary', 'text', 'one', 'A summary, in prose, of the terms the policy actually sets out — the obligations, controls, and procedures it describes. Summarise what is there; do not list what is absent.', NULL, 63),
  (1, 1, 'aml-policies-summary', 'f_policy_scope_notes', 'Policy Scope Notes', 'text', 'one', 'Stated scope and limits: which entities, jurisdictions, or business lines the policy covers, and any matter it expressly says is out of scope or governed by a separate document.', NULL, 64),
  (1, 1, 'financial-output', 'f_gross_revenue', 'Gross Revenue', 'text', 'many', '3 years (one entry per year, with year and currency).', NULL, 65),
