  (1, 1, 'trade-flow-profile', 'f_flow_stages_sought', 'Flow Stages Sought', 'text', 'many', 'Which stages of the trade cycle financing is sought for. Use only stages the document actually identifies, from: upstream warehouse, inland transport, seaborne transit, downstream warehouse, receivables. State each with any detail given (duration, value, location).', NULL, 88),
  (1, 1, 'trade-flow-profile', 'f_turnover_stated', 'Turnover Stated', 'text', 'one', 'Annual turnover or trading volume as NARRATED in this document (not from financial statements). Include the period and currency stated.', NULL, 89),
  (1, 1, 'trade-flow-profile', 'f_margins_stated', 'Margins Stated', 'text', 'one', 'Gross or trading margin as NARRATED in this document, per unit or per percentage, with the basis stated.', NULL, 90),
