  (1, 1, 'trade-flow-profile', 'f_suppliers.name', 'Name', 'entity_name', 'group', 'supplier identifier exactly as the source gives it: the company name where named, or the row label verbatim (e.g. ''Supplier 1'') where the source uses positional labels. Transcribe; never substitute, infer or blank it.', 'f_suppliers', 93),
  (1, 1, 'trade-flow-profile', 'f_suppliers.location', 'Location', 'text', 'group', 'country, region, or city of the supplier, if stated', 'f_suppliers', 94),
