  (2, 1, 'articles', 'Articles of Association', 'corp', 'The entity''s articles of association or constitutional document, setting out share classes, director powers and internal rules.', 'text', 0, 0),
  (2, 1, 'bylaws', 'Bylaws', 'corp', 'Internal governance rules or bylaws adopted by the entity.', 'text', 0, 1),
  (2, 1, 'good-standing', 'Certificate of Good Standing', 'corp', 'A certificate issued by a registry confirming the entity exists and is in good standing at a stated date.', 'text', 0, 2),
  (2, 1, 'certificate-of-incorporation', 'Certificate of Incorporation', 'corp', 'The registry certificate recording that the entity was incorporated: legal name, registration number and date.', 'text', 0, 3),
  (2, 1, 'board-resolution', 'Board Resolution', 'corp', 'A minuted resolution of the board or members, typically authorising an act or appointing signatories.', 'text', 0, 4),
  (2, 1, 'beneficial-ownership', 'Beneficial Ownership Declaration', 'corp', 'A declaration naming the ultimate beneficial owners and their percentage holdings.', 'forms', 0, 5),
  (2, 1, 'regulatory-filings', 'Regulatory Filings', 'corp', 'An extract or filing made to a company registry or regulator: annual return, register extract, officer or shareholder filing. Records what the registry holds, not what the entity says about itself.', 'forms', 0, 6),
  (2, 1, 'cap-table', 'Cap Table or Share Instrument', 'corp', 'A share register, cap table, or an instrument affecting share ownership: share purchase agreement, option, warrant or pledge.', 'forms', 0, 7),
  (2, 1, 'aml-policy', 'AML Policy', 'kyc-aml-pep', 'The entity''s own anti-money-laundering or counter-terrorist-financing policy document.', 'text', 0, 8),
