  (2, 1, 'bank-statements', 'Bank Statements', 'financial', 'Statements of account issued by a bank showing transactions over a period.', 'forms', 1, 17),
  (2, 1, 'aging-reports', 'Aged Debtors or Creditors', 'financial', 'An aged debtors or aged creditors schedule showing amounts outstanding by age.', 'forms', 1, 18),
  (2, 1, 'counterparty-list', 'Customer or Supplier List', 'business', 'A schedule or list OF the entity''s customers, buyers or suppliers - names, locations, volumes or terms, usually tabular. A list of third parties, not a questionnaire about the entity itself.', 'text', 0, 19),
  (2, 1, 'market-analysis', 'Market Analysis', 'business', 'Analysis or commentary on the market, sector or commodity the entity trades in.', 'text', 0, 20),
  (2, 1, 'operations-memo', 'Operations Memorandum', 'business', 'A description of how the entity operates: sourcing, logistics, processing, warehousing, settlement.', 'text', 0, 21),
  (2, 1, 'trade-references', 'Trade References', 'business', 'A reference given by a trading partner, bank or customer about dealings with the entity.', 'text', 0, 22),
  (2, 1, 'trade-summary', 'Trade Summary', 'business', 'A summary of completed or planned trades, typically tabular: counterparties, commodities, volumes, values.', 'text', 0, 23),
  (2, 1, 'licenses-certificates', 'Licences and Certificates', 'business', 'A licence, permit, registration or certification held by a named party: regulatory licence, import permit, quality or scheme certification.', 'forms', 0, 24),
