  (2, 1, 'KYC', 'f_persons.residential_address', 'Residential Address', 'address', 'group', 'residential address, if stated', 'f_persons', 51),
  (2, 1, 'KYC', 'f_persons.id_document', 'Id Document', 'identifier', 'group', 'ID document type and number, if stated', 'f_persons', 52),
