  (2, 1, 'KYC', 'f_persons', 'Persons', 'group', 'group', 'One record per natural person (UBO, director, officer or authorised signatory) OF THE ENTITY named in the document. Include only persons actually named; do not invent. Do NOT include a person who merely certified, witnessed, stamped, notarised or filed the document, or a registry official processing it - they are not parties to the entity.', 'f_persons', 54),
  (2, 1, 'KYC', 'f_financial_counterparties.name', 'Name', 'entity_name', 'group', 'institution name exactly as the source gives it; transcribe, never expand an abbreviation or correct a spelling', 'f_financial_counterparties', 55),
  (2, 1, 'KYC', 'f_financial_counterparties.type', 'Type', 'text', 'group', 'one of: bank, insurer, insurance-broker, warehouse. Use the term the source supports; if the source does not make the type clear, leave null rather than guessing', 'f_financial_counterparties', 56),
  (2, 1, 'KYC', 'f_financial_counterparties.role', 'Role', 'text', 'group', 'what it does for the entity as stated (e.g. operating account, collections, stock throughput cover, credit insurance, storage), if stated', 'f_financial_counterparties', 57),
  (2, 1, 'KYC', 'f_financial_counterparties.jurisdiction', 'Jurisdiction', 'text', 'group', 'country or location of the institution, if stated', 'f_financial_counterparties', 58),
  (2, 1, 'KYC', 'f_financial_counterparties', 'Financial Counterparties', 'group', 'group', 'One record per BANK, INSURER, INSURANCE BROKER or WAREHOUSE/COLLATERAL OPERATOR the source connects to the entity. These are the counterparties a lender must see: who holds the cash, who carries the cargo and credit risk, and who holds the goods. Capture each one the source identifies, including those also named elsewhere in the document. Do not include buyers, suppliers, parents, subsidiaries, inspection or certification bodies, or regulators - those belong to other fields.', 'f_financial_counterparties', 59),
  (2, 1, 'aml-policies-summary', 'f_policy_provided', 'Policy Provided', 'text', 'one', 'Whether this document is, or contains, an AML/CTF policy or programme description. Answer ''yes'' or ''no'' based only on what the document is. Do not comment on whether the counterparty has a programme — only on what this document contains.', NULL, 60),
  (2, 1, 'aml-policies-summary', 'f_policy_document', 'Policy Document', 'text', 'one', 'Identification of the document as stated: title, issuing entity, version, effective or approval date, and review cycle, to the extent given.', NULL, 61),
  (2, 1, 'aml-policies-summary', 'f_compliance_officer', 'Compliance Officer', 'text', 'one', 'The named compliance officer, MLRO, or responsible person, with title, if the document states one.', NULL, 62),
  (2, 1, 'aml-policies-summary', 'f_policy_summary', 'Policy Summary', 'text', 'one', 'A summary, in prose, of the terms the policy actually sets out — the obligations, controls, and procedures it describes. Summarise what is there; do not list what is absent.', NULL, 63),
  (2, 1, 'aml-policies-summary', 'f_policy_scope_notes', 'Policy Scope Notes', 'text', 'one', 'Stated scope and limits: which entities, jurisdictions, or business lines the policy covers, and any matter it expressly says is out of scope or governed by a separate document.', NULL, 64),
  (2, 1, 'financial-output', 'f_gross_revenue', 'Gross Revenue', 'text', 'many', '3 years (one entry per year, with year and currency).', NULL, 65),
  (2, 1, 'financial-output', 'f_cost_of_goods', 'Cost Of Goods', 'text', 'many', '3 years.', NULL, 66),
  (2, 1, 'financial-output', 'f_trade_history_notes', 'Trade History Notes', 'text', 'many', 'Stated history, volume, length of dealing; commodities, origins/destinations, suppliers/buyers.', NULL, 67),
  (2, 1, 'financial-output', 'f_commissions', 'Commissions', 'text', 'many', '3 years.', NULL, 68),
