  (2, 1, 'trade-flow-profile', 'f_origins', 'Origins', 'text', 'many', 'Countries, regions, or ports the goods are sourced or shipped FROM, as stated.', NULL, 86),
  (2, 1, 'trade-flow-profile', 'f_destinations', 'Destinations', 'text', 'many', 'Countries, regions, or ports the goods are delivered TO, as stated.', NULL, 87),
  (2, 1, 'trade-flow-profile', 'f_flow_stages_sought', 'Flow Stages Sought', 'text', 'many', 'Which stages of the trade cycle financing is sought for. Use only stages the document actually identifies, from: upstream warehouse, inland transport, seaborne transit, downstream warehouse, receivables. State each with any detail given (duration, value, location).', NULL, 88),
  (2, 1, 'trade-flow-profile', 'f_turnover_stated', 'Turnover Stated', 'text', 'one', 'Annual turnover or trading volume as NARRATED in this document (not from financial statements). Include the period and currency stated.', NULL, 89),
  (2, 1, 'trade-flow-profile', 'f_margins_stated', 'Margins Stated', 'text', 'one', 'Gross or trading margin as NARRATED in this document, per unit or per percentage, with the basis stated.', NULL, 90),
  (2, 1, 'trade-flow-profile', 'f_headquarters', 'Headquarters', 'address', 'one', 'Where the business is actually headquartered or principally operates from, if stated. This may differ from the registered office.', NULL, 91),
  (2, 1, 'trade-flow-profile', 'f_financing_requested', 'Financing Requested', 'text', 'one', 'The financing being sought: amount, currency, tenor, facility type, advance rate, and pricing expectation, to the extent stated.', NULL, 92),
  (2, 1, 'trade-flow-profile', 'f_suppliers.name', 'Name', 'entity_name', 'group', 'supplier identifier exactly as the source gives it: the company name where named, or the row label verbatim (e.g. ''Supplier 1'') where the source uses positional labels. Transcribe; never substitute, infer or blank it.', 'f_suppliers', 93),
  (2, 1, 'trade-flow-profile', 'f_suppliers.location', 'Location', 'text', 'group', 'country, region, or city of the supplier, if stated', 'f_suppliers', 94),
  (2, 1, 'trade-flow-profile', 'f_suppliers.commodity', 'Commodity', 'text', 'group', 'what is bought from this supplier, if stated', 'f_suppliers', 95),
  (2, 1, 'trade-flow-profile', 'f_suppliers.payment_terms', 'Payment Terms', 'text', 'group', 'payment terms expected or in place with this supplier (e.g. CAD, prepayment, 30 days, LC), if stated', 'f_suppliers', 96),
  (2, 1, 'trade-flow-profile', 'f_suppliers.relationship_length', 'Relationship Length', 'text', 'group', 'how long the entity has traded with them, if stated', 'f_suppliers', 97),
  (2, 1, 'trade-flow-profile', 'f_suppliers', 'Suppliers', 'group', 'group', 'One record per supplier the source identifies, whether the source lists them in a table or describes them in prose. Capture every supplier it identifies, in the order given. Where a supplier is identified only by a positional or placeholder label rather than a company name (e.g. ''Supplier 1'' in an anonymised schedule), still capture the record and put that label in `name` exactly as written: whether such a label counts as a name is not a judgement to make here, and the remaining details are needed either way. Never substitute or infer a name. Do not add suppliers the source does not identify.', 'f_suppliers', 98),
  (2, 1, 'trade-flow-profile', 'f_buyers.name', 'Name', 'entity_name', 'group', 'buyer identifier exactly as the source gives it: the company name where named, or the row label verbatim (e.g. ''Buyer 1'') where the source uses positional labels. Transcribe; never substitute, infer or blank it.', 'f_buyers', 99),
  (2, 1, 'trade-flow-profile', 'f_buyers.location', 'Location', 'text', 'group', 'country, region, or city of the buyer, if stated', 'f_buyers', 100),
  (2, 1, 'trade-flow-profile', 'f_buyers.commodity', 'Commodity', 'text', 'group', 'what is sold to this buyer, if stated', 'f_buyers', 101),
  (2, 1, 'trade-flow-profile', 'f_buyers.payment_terms', 'Payment Terms', 'text', 'group', 'payment terms sought or in place with this buyer (e.g. CAD, LC, open account, days credit), if stated', 'f_buyers', 102),
  (2, 1, 'trade-flow-profile', 'f_buyers.relationship_length', 'Relationship Length', 'text', 'group', 'how long the entity has traded with them, if stated', 'f_buyers', 103),
  (2, 1, 'trade-flow-profile', 'f_buyers', 'Buyers', 'group', 'group', 'One record per buyer or customer the source identifies, whether the source lists them in a table or describes them in prose. Capture every buyer it identifies, in the order given. Where a buyer is identified only by a positional or placeholder label rather than a company name (e.g. ''Buyer 1'' in an anonymised schedule), still capture the record and put that label in `name` exactly as written: whether such a label counts as a name is not a judgement to make here, and the remaining details are needed either way. Never substitute or infer a name. Do not add buyers the source does not identify.', 'f_buyers', 104);

